"""Prices for the tiny shop."""

TAX_RATE = 0.08


def apply_discount(price, percent):
    """Return the price after a percentage discount."""
    return round(price * (1 - percent / 100), 2)


def with_tax(price):
    return round(price * (1 + TAX_RATE), 2)

